const prompt = PromptTemplate.fromTemplate("You are an helpful agent. User: {input}");
const { RunnableSequence }  = require('@langchain/core/runnables');
let tools = [];
const llmWithTools = llm[0].bindTools(tools);
const chain = RunnableSequence.from([prompt, llmWithTools]);
const results = await chain.invoke({ input: userMessage });
return [{
  json: {
    output: results.content
  }
}];

